const apiKey = $input.first().json.body.api_key;
if (!apiKey || apiKey !== $env.N8N_API_KEY) throw new Error('Unauthorized');
const body = $input.first().json.body;
if (!body.brand_id) throw new Error('Missing brand_id');
return [{
  json: {
    brand_id: body.brand_id,
    search_keyword: body.search_keyword || '',
    content_type: body.content_type || '',
    target_reader: body.target_reader || '',
    recency_days: body.recency_days || '',
    log_id: 'td-' + $now.toISO().replace(/[^0-9]/g, '').slice(0, 17),
    started_at: $now.toISO()
  }
}];

const brand = $input.first().json;
const req = $('驗證請求').first().json;
const keyword = (req.search_keyword || '').trim();
const theme = brand.theme || '社群行銷';
const audience = brand.target_audience || '一般消費者';
const year = new Date().getFullYear();
let queries;
if (keyword) {
  // 使用者明確指定關鍵字：擴成 3 個變體
  queries = [
    keyword,
    `${keyword} ${year}`,
    `${keyword} ${audience}`
  ];
} else {
  queries = [
    `${theme} 趨勢 ${year}`,
    `${theme} ${audience} 熱門話題`,
    `${brand.brand_name || ''} 產業 最新消息`
  ].filter(Boolean);
}
// recency → tbs
const days = parseInt(req.recency_days, 10);
let tbs = '';
if (days === 7) tbs = 'qdr:w';
else if (days === 30) tbs = 'qdr:m';
else if (days === 90) tbs = 'qdr:m3';
return queries.map(q => ({ json: { query: q, brand, tbs } }));

// 彙整所有搜尋結果
const allResults = [];

for (const item of $input.all()) {
  const organic = item.json.organic || [];
  for (const result of organic) {
    allResults.push({
      title: result.title,
      link: result.link,
      snippet: result.snippet || ''
    });
  }
}

// 去重（依 link）
const seen = new Set();
const unique = allResults.filter(r => {
  if (seen.has(r.link)) return false;
  seen.add(r.link);
  return true;
}).slice(0, 20);

return [{
  json: {
    results: unique,
    brand_id: $('驗證請求').first().json.brand_id,
    count: unique.length
  }
}];

