const req = $('驗證請求').first().json;
const brandId = req.brand_id;
const response = $input.first().json;
const content = response.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
let topics;
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  topics = JSON.parse(cleaned);
} catch (e) {
  topics = [];
}
// 最多 7 個
topics = topics.slice(0, 7);
const now = new Date().toISOString();
return topics.map((t, i) => ({
  json: {
    topic_id: `topic-${Date.now()}-${i}`,
    brand_id: brandId,
    topic_title: t.topic_title || t.title || '',
    source_url: t.source_url || t.url || '',
    relevance_score: String(t.relevance_score || 0),
    status: 'pending',
    brand_relevance: t.brand_relevance || '',
    suggested_angles: t.suggested_angles || '',
    content_type: t.content_type || req.content_type || '',
    target_reader: req.target_reader || '',
    search_keyword: req.search_keyword || '',
    archived_at: '',
    created_at: now
  }
}));

// Sequential fan-out with 15s stagger — avoids Gemini free-tier RPM
const apiKey = $env.N8N_API_KEY;
const brandId = $('驗證請求').first().json.brand_id;
const items = $input.all();
let dispatched = 0;
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const topic_id = item.json.topic_id;
  const topic_title = item.json.topic_title;
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://wing.zeabur.app/webhook/content-generation',
      body: { api_key: apiKey, brand_id: brandId, topic_id, topic_title },
      json: true,
      timeout: 10000
    });
    dispatched++;
  } catch (e) { /* fire-and-forget */ }
  // 15 秒 stagger，給 Gemini 4 RPM 不會爆
  if (i < items.length - 1) {
    await new Promise(r => setTimeout(r, 15000));
  }
}
return [{ json: { topics_dispatched: dispatched } }];

